argsPayload:
{
  "command": "echo \"== item count (quoted) ==\"; grep -o '<item>' /tmp/gn_quote.xml | wc -l; echo \"== item count (plain) ==\"; grep -o '<item>' /tmp/gn_nospace.xml | wc -l; echo; echo \"== full redirect chain ==\"; LINK=$(grep -o '<link>https://news.google.com/rss/articles/[^<]*' /tmp/gn_quote.xml | head -1 | sed 's/<link>//'); curl -s -o /dev/null --max-time 25 -w 'hop1: %{url_effective}\\n' -L -w 'final: %{url_effective}\\n' -w 'code: %{http_code}\\n' -w 'redirects: %{num_redirects}\\n' \"$LINK\" 2>&1 | tail -5; echo; echo \"== -L verbose final URL (grep location) ==\"; curl -s -o /dev/null --max-time 25 -L -w 'final_url: %{url_effective}\\n' \"$LINK\""
}

{
  "command": "LINK=$(grep -o '<link>https://news.google.com/rss/articles/[^<]*' /tmp/gn_quote.xml | head -1 | sed 's/<link>//'); curl -s --max-time 25 -A 'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36' -L \"$LINK\" -o /tmp/gn_hop2.html -w 'code: %{http_code} size: %{size_download}\\n'; echo \"== look for redirect hints ==\"; grep -o 'location.replace([^)]*)' /tmp/gn_hop2.html | head -3; grep -o 'window.location[^;]*' /tmp/gn_hop2.html | head -3; grep -o 'data-n-a-ids=\"[^\"]*\"' /tmp/gn_hop2.html | head -3; echo; echo \"== title ==\"; grep -o '<title>[^<]*' /tmp/gn_hop2.html | head -1"
}

{
  "command": "TOKEN=$(grep -o '<guid isPermaLink=\"false\">[^<]*' /tmp/gn_quote.xml | head -1 | sed 's/<guid isPermaLink=\"false\">//'); echo \"token len: ${#TOKEN}\"; echo \"== base64 decode (urlsafe, padded) ==\"; echo \"$TOKEN\" | tr '_-' '/+' | base64 -d 2>/dev/null | strings | head -30"
}

{
  "command": "LINK=$(grep -o '<link>https://news.google.com/rss/articles/[^<]*' /tmp/gn_quote.xml | head -1 | sed 's/<link>//;s/?oc=5//'); echo \"== without oc param ==\"; curl -s -o /dev/null --max-time 20 -w 'final: %{url_effective} | redirects: %{num_redirects}\\n' -L \"$LINK\"; echo \"== oc=5 + explicit hl=US ==\"; curl -s -o /dev/null --max-time 20 -w 'final: %{url_effective} | redirects: %{num_redirects}\\n' -L \"$LINK?oc=5&hl=en-US&gl=US&ceid=US:en\""
}

{
  "command": "echo \"== search for article URLs in SPA ==\"; grep -o 'https://www\\.independent\\.ie[^\"\\\\]*' /tmp/gn_hop2.html | head -3; grep -o 'https://[a-z.]*independent[a-z.]*[^\"\\\\ ]*' /tmp/gn_hop2.html | head -5; echo; echo \"== look for batchexecute JSON payload keys ==\"; grep -o 'article-url[^,]*' /tmp/gn_hop2.html | head -3; grep -o '\"url\":\"[^\"]*independent[^\"]*\"' /tmp/gn_hop2.html | head -3"
}

{
  "command": "echo \"== rate limit test: 10 consecutive search requests ==\"; for i in $(seq 1 10); do CODE=$(curl -s -o /dev/null --max-time 20 -w '%{http_code}' \"https://news.google.com/rss/search?q=%22test+news%22&hl=en-US&gl=US&ceid=US:en\"); echo \"req $i: HTTP $CODE\"; sleep 0.5; done",
  "timeout": 120
}

{
  "command": "echo \"== burst: 10 rapid requests no sleep ==\"; for i in $(seq 1 10); do CODE=$(curl -s -o /dev/null --max-time 20 -w '%{http_code}' \"https://news.google.com/rss/search?q=%22sanctions%22&hl=en-US&gl=US&ceid=US:en\"); printf \"req %s:%s \" \"$i\" \"$CODE\"; done; echo; echo \"== 30 more rapid ==\"; for i in $(seq 1 30); do CODE=$(curl -s -o /dev/null --max-time 20 -w '%{http_code}' \"https://news.google.com/rss/search?q=%22sanctions%22&hl=en-US&gl=US&ceid=US:en\"); printf \"%s \" \"$CODE\"; done; echo",
  "timeout": 180
}

arguments.command:
LINK=$(grep -o '<link>https://news.google.com/rss/articles/[^<]*' /tmp/gn_quote.xml | head -1 | sed 's/<link>//;s/?oc=5//'); echo "== oc=1 =="; curl -s -o /dev/null --max-time 20 -w 'redirects:%{num_redirects} final:%{url_effective}
' -L "$LINK?oc=1"; echo "== oc=3 =="; curl -s -o /dev/null --max-time 20 -w 'redirects:%{num_redirects} final:%{url_effective}
' -L "$LINK?oc=3"; echo "== no oc, no follow, check first response =="; curl -s -o /dev/null --max-time 20 -w 'code:%{http_code} redirects:%{num_redirects}
' "$LINK"; echo "== description sample (raw) =="; grep -o '<description>[^<]*' /tmp/gn_quote.xml | head -1 | cut -c1-400

