{
  "command": "echo \"== case-insensitive domain search in SPA ==\"; grep -oi 'independent\\.ie' /tmp/gn_hop2.html | head -3; echo \"== AF_initDataCallback / articleUrl ==\"; grep -o 'articleUrl[^,]*' /tmp/gn_hop2.html | head -5; grep -c 'batchexecute' /tmp/gn_hop2.html; echo \"== what the SPA has ==\"; grep -o 'window.APP_INITIALIZATION_STATE[^;]\\{0,80\\}' /tmp/gn_hop2.html | head -2 | cut -c1-200"
}

{
  "command": "LINK=$(grep -o '<link>https://news.google.com/rss/articles/[^<]*' /tmp/gn_quote.xml | head -1 | sed 's/<link>//;s/?oc=5//'); echo \"== oc=1 ==\"; curl -s -o /dev/null --max-time 20 -w 'redirects:%{num_redirects} final:%{url_effective}\\n' -L \"$LINK?oc=1\"; echo \"== oc=3 ==\"; curl -s -o /dev/null --max-time 20 -w 'redirects:%{num_redirects} final:%{url_effective}\\n' -L \"$LINK?oc=3\"; echo \"== no oc, no follow, check first response ==\"; curl -s -o /dev/null --max-time 20 -w 'code:%{http_code} redirects:%{num_redirects}\\n' \"$LINK\"; echo \"== description sample (raw) ==\"; grep -o '<description>[^<]*' /tmp/gn_quote.xml | head -1 | cut -c1-400"
}

{
  "command": "echo \"== when=1d param ==\"; curl -s --max-time 20 'https://news.google.com/rss/search?q=%22EU+sanctions%22&hl=en-US&gl=US&ceid=US:en&when=1d' -o /tmp/gn_when.xml -w 'HTTP %{http_code} size %{size_download}\\n'; grep -o '<item>' /tmp/gn_when.xml | wc -l; echo \"== when=1h ==\"; curl -s --max-time 20 'https://news.google.com/rss/search?q=%22EU+sanctions%22&hl=en-US&gl=US&ceid=US:en&when=1h' -o /tmp/gn_when1h.xml -w 'HTTP %{http_code} size %{size_download}\\n'; grep -o '<item>' /tmp/gn_when1h.xml | wc -l; echo \"== pubDate freshness check (1h) ==\"; grep -o '<pubDate>[^<]*' /tmp/gn_when1h.xml | head -3"
}

{
  "command": "echo \"== same items? diff guid sets ==\"; diff <(grep -o '<guid isPermaLink=\"false\">[^<]*' /tmp/gn_nospace.xml) <(grep -o '<guid isPermaLink=\"false\">[^<]*' /tmp/gn_when1h.xml) > /dev/null && echo \"IDENTICAL → when ignored\" || echo \"DIFFERENT → when has effect\"; echo; echo \"== vs quoted(no when) ==\"; diff <(grep -o '<guid isPermaLink=\"false\">[^<]*' /tmp/gn_quote.xml) <(grep -o '<guid isPermaLink=\"false\">[^<]*' /tmp/gn_when.xml) > /dev/null && echo \"IDENTICAL → when ignored\" || echo \"DIFFERENT → when has effect\""
}

{
  "command": "diff <(grep -o '<guid isPermaLink=\"false\">[^<]*' /tmp/gn_quote.xml) <(grep -o '<guid isPermaLink=\"false\">[^<]*' /tmp/gn_when.xml) > /dev/null && echo \"when=1d vs no-when (both quoted): IDENTICAL → when ignored\" || echo \"when=1d vs no-when: DIFFERENT → when has effect\"; diff <(grep -o '<guid isPermaLink=\"false\">[^<]*' /tmp/gn_quote.xml) <(grep -o '<guid isPermaLink=\"false\">[^<]*' /tmp/gn_when1h.xml) > /dev/null && echo \"when=1h vs no-when: IDENTICAL → when ignored\" || echo \"when=1h vs no-when: DIFFERENT → when has effect\"; echo; echo \"== oldest pubDate in each ==\"; for f in gn_quote gn_when gn_when1h; do echo -n \"$f: \"; grep -o '<pubDate>[^<]*' /tmp/$f.xml | sed 's/<pubDate>//' | sort | head -1; done"
}

